using AcademyDesk.Api.Data;using AcademyDesk.Api.Domain.Entities;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;
namespace AcademyDesk.Api.Controllers;
[ApiController][Route("api/academies/{academyId:guid}/access-reviews")]public sealed class AccessReviewsController(AcademyDeskDbContext db):ControllerBase{[HttpGet]public async Task<ActionResult> List(Guid academyId,CancellationToken t)=>Ok(await db.AccessReviews.AsNoTracking().Where(x=>x.AcademyId==academyId).OrderByDescending(x=>x.ReviewedAtUtc).ToListAsync(t));[HttpPost]public async Task<ActionResult> SignOff(Guid academyId,AccessReviewRequest r,CancellationToken t){db.AccessReviews.Add(new AccessReview{AcademyId=academyId,Notes=r.Notes?.Trim()});if(r.CreateFollowUp)db.AdminWorkItems.Add(new AdminWorkItem{AcademyId=academyId,Type="AccessReview",Title="Resolve access review actions",Description=r.Notes?.Trim(),Priority="High"});await db.SaveChangesAsync(t);return Ok();}}
public sealed record AccessReviewRequest(string? Notes,bool CreateFollowUp);
